//go:build ppc64le

package floats

// VSX kernels (POWER8 baseline, gated on hasVSX like the float32 reductions):
// the float64 Add, Sub, Mul, Div, Sqrt of go-ndarray and the pairwise-sum block,
// generated by go-asmgen (lanes_ppc64le_gen.go) into lanes_ppc64le.s. One IEEE
// operation per element, no fused instruction: bit-identical to the scalar loops.
// The callers pass every slice already sliced to the common length.
//
//go:noescape
func addVSX(dst, a, b *float64, n int)

//go:noescape
func subVSX(dst, a, b *float64, n int)

//go:noescape
func mulVSX(dst, a, b *float64, n int)

//go:noescape
func divVSX(dst, a, b *float64, n int)

//go:noescape
func sqrtVSX(dst, src *float64, n int)

// pwBlockVSX is the 8 <= n <= 128 block of DOUBLE_pairwise_sum.
//
//go:noescape
func pwBlockVSX(a *float64, n int) float64

func add(dst, a, b []float64) {
	if len(a) == 0 || !hasVSX {
		addRef(dst, a, b)
		return
	}
	addVSX(&dst[0], &a[0], &b[0], len(a))
}

func sub(dst, a, b []float64) {
	if len(a) == 0 || !hasVSX {
		subRef(dst, a, b)
		return
	}
	subVSX(&dst[0], &a[0], &b[0], len(a))
}

func mul(dst, a, b []float64) {
	if len(a) == 0 || !hasVSX {
		mulRef(dst, a, b)
		return
	}
	mulVSX(&dst[0], &a[0], &b[0], len(a))
}

func div(dst, a, b []float64) {
	if len(a) == 0 || !hasVSX {
		divRef(dst, a, b)
		return
	}
	divVSX(&dst[0], &a[0], &b[0], len(a))
}

func sqrt(dst, src []float64) {
	if len(src) == 0 || !hasVSX {
		sqrtRef(dst, src)
		return
	}
	sqrtVSX(&dst[0], &src[0], len(src))
}

func clampScalar(dst, v []float64, lo, hi float64) { clampScalarRef(dst, v, lo, hi) }

func pairwiseBlock(a []float64) float64 {
	if !hasVSX {
		return pairwiseBlockRef(a)
	}
	return pwBlockVSX(&a[0], len(a))
}
